      + '.cadv .h{stroke:var(--ink-3);stroke-width:.9px;stroke-dasharray:5 3}.cadv .c{stroke:var(--ink-3);stroke-width:.7px;stroke-dasharray:12 3 2 3}.cadv .d{stroke:var(--dim);stroke-width:.8px}'
